const MAX_E: usize = 8;
const MAX_C: usize = 46;
const MAX_WORDS: usize = 127;
const D: i32 = 4;
const Cell = struct { depth:i32=0, prefix:i32=0, lo:i32=0, alt:i32=0, x0:i32=0, y0:i32=0, x1:i32=0, y1:i32=0, endpoints:i32=0 };
const Edge = struct { x0:i32=0, y0:i32=0, x1:i32=0, y1:i32=0, start:i32=-1, end:i32=-1, negative:bool=false };
const Point = struct { x:i32, y:i32 };
const Exit = struct { edge:usize, side:i32, num:i64, den:i64 };

fn orient(a:Point,b:Point,c:Point)i64{return @as(i64,b.x-a.x)*@as(i64,c.y-a.y)-@as(i64,b.y-a.y)*@as(i64,c.x-a.x);}
fn onSegment(a:Point,b:Point,p:Point)bool{return p.x>=@min(a.x,b.x) and p.x<=@max(a.x,b.x) and p.y>=@min(a.y,b.y) and p.y<=@max(a.y,b.y);}
fn intersects(a:Point,b:Point,c:Point,d:Point)bool{
    const o1=orient(a,b,c);const o2=orient(a,b,d);const o3=orient(c,d,a);const o4=orient(c,d,b);
    if((o1==0 and onSegment(a,b,c)) or (o2==0 and onSegment(a,b,d)) or (o3==0 and onSegment(c,d,a)) or (o4==0 and onSegment(c,d,b)))return true;
    return o1*o2<0 and o3*o4<0;
}
fn positiveKey(x:i32,y:i32)i32{var key:i32=0;var bit:i32=7;while(bit>=4):(bit-=1){key=(key<<2)|(((x>>@intCast(bit))&1)<<1)|((y>>@intCast(bit))&1);}return key;}
fn altPrefix(depth:i32,prefix:i32)i32{const map=[_]i32{2,0,3,1};var out:i32=0;var shift=2*(depth-1);while(shift>=0):(shift-=2){out=(out<<2)|map[@intCast((prefix>>@intCast(shift))&3)];}return out;}
fn makeBox(cell:*Cell)void{var x:i32=0;var y:i32=0;var shift=2*(cell.depth-1);while(shift>=0):(shift-=2){const q=(cell.prefix>>@intCast(shift))&3;x=(x<<1)|(q>>1);y=(y<<1)|(q&1);}const side:i32=256>>@intCast(cell.depth);cell.x0=x*side;cell.y0=y*side;cell.x1=cell.x0+side;cell.y1=cell.y0+side;}
fn findCell(cells:*[MAX_C]Cell,c:usize,key:i32)i32{for(0..c)|i|{const span:i32=1<<@intCast(2*(D-cells[i].depth));if(key>=cells[i].lo and key<cells[i].lo+span)return @intCast(i);}return -1;}
fn sweepBox(cell:Cell,rotated:bool)[4]i32{if(rotated)return .{256-cell.y1,cell.x0,256-cell.y0,cell.x1};return .{cell.x0,cell.y0,cell.x1,cell.y1};}
fn sweepEdge(e:Edge,rotated:bool)[2]Point{if(rotated)return .{.{.x=256-e.y0,.y=e.x0},.{.x=256-e.y1,.y=e.x1}};return .{.{.x=e.x0,.y=e.y0},.{.x=e.x1,.y=e.y1}};}
fn segmentBox(e:Edge,cell:Cell,rotated:bool)bool{const box=sweepBox(cell,rotated);const ab=sweepEdge(e,rotated);const x0=box[0];const y0=box[1];const x1=box[2];const y1=box[3];const a=ab[0];const b=ab[1];if((a.x>=x0 and a.x<=x1 and a.y>=y0 and a.y<=y1) or (b.x>=x0 and b.x<=x1 and b.y>=y0 and b.y<=y1))return true;const corners=[_]Point{.{.x=x0,.y=y0},.{.x=x1,.y=y0},.{.x=x1,.y=y1},.{.x=x0,.y=y1}};for(0..4)|i|if(intersects(a,b,corners[i],corners[(i+1)&3]))return true;return false;}
fn append(path:*[33]Point,n:*usize,p:Point)bool{if(n.*>0 and path[n.*-1].x==p.x and path[n.*-1].y==p.y)return true;if(n.*>=33)return false;path[n.*]=p;n.*+=1;return true;}
fn frontier(cells:*[MAX_C]Cell,c:usize,order:*[MAX_C]usize,cut:usize,rotated:bool,path:*[33]Point,path_n:*usize,corner:*usize)bool{
    var rank:[MAX_C]usize=@splat(0);for(0..c)|i|rank[order[i]]=i;var atom:[256]i32=@splat(-1);
    for(0..c)|pos|{const id=order[pos];const start=if(rotated)cells[id].alt else cells[id].lo;const span:i32=1<<@intCast(2*(D-cells[id].depth));var k=start;while(k<start+span):(k+=1)atom[@intCast(k)]=@intCast(id);}
    var processed:[256]bool=@splat(false);
    for(0..256)|key|{const id=atom[key];if(id<0)return false;var x:i32=0;var y:i32=0;var shift:i32=6;while(shift>=0):(shift-=2){const q=( @as(i32,@intCast(key))>>@intCast(shift))&3;x=(x<<1)|(q>>1);y=(y<<1)|(q&1);}processed[@intCast(x*16+y)]=rank[@intCast(id)]<cut;}
    var h:[16]i32=@splat(0);for(0..16)|x|{var v:i32=0;while(v<16 and processed[x*16+@as(usize,@intCast(v))]){v+=1;}for(0..16)|y|if(processed[x*16+y]!=( @as(i32,@intCast(y))<v))return false;h[x]=v;if(x>0 and h[x-1]<v)return false;}
    path_n.*=0;if(!append(path,path_n,.{.x=0,.y=256}))return false;var y:i32=15;while(y>=h[0]):(y-=1){if(!append(path,path_n,.{.x=0,.y=y*16}))return false;}
    for(0..16)|x|{if(!append(path,path_n,.{.x=@as(i32,@intCast(x+1))*16,.y=h[x]*16}))return false;const next=if(x<15)h[x+1] else 0;var yy=h[x]-1;while(yy>=next):(yy-=1){if(!append(path,path_n,.{.x=@as(i32,@intCast(x+1))*16,.y=yy*16}))return false;}}
    if(path[0].x!=0 or path[0].y!=256 or path[path_n.*-1].x!=256 or path[path_n.*-1].y!=0)return false;const box=sweepBox(cells[order[cut]],rotated);for(0..path_n.*)|i|if(path[i].x==box[0] and path[i].y==box[1]){corner.*=i;return true;};return false;
}
fn frontierSegment(a:Point,b:Point,path:*[33]Point,n:usize)i32{var found:i32=-1;for(0..n-1)|i|if(intersects(a,b,path[i],path[i+1])){if(found>=0)return -2;found=@intCast(i);};return found;}
fn exitForCell(a:Point,b:Point,box:[4]i32,id:usize) ?Exit{const dx:i64=b.x-a.x;const dy:i64=b.y-a.y;var found:?Exit=null;if(dy>0){const yd:i64=box[3]-a.y;const num:i64=@as(i64,a.x)*dy+yd*dx;if(yd>0 and yd<dy and @as(i64,box[0])*dy<num and num<@as(i64,box[2])*dy)found=.{.edge=id,.side=0,.num=num,.den=dy};}if(dx>0){const xd:i64=box[2]-a.x;const num:i64=@as(i64,a.y)*dx+xd*dy;if(xd>0 and xd<dx and @as(i64,box[1])*dx<num and num<@as(i64,box[3])*dx){if(found!=null)return null;found=.{.edge=id,.side=1,.num=num,.den=dx};}}return found;}
fn exitLess(a:Exit,b:Exit)bool{const l=a.num*b.den;const r=b.num*a.den;return l<r or (l==r and a.edge<b.edge);}
fn runSweep(cells:*[MAX_C]Cell,c:usize,edges:*[MAX_E]Edge,n:usize,endpoints:*[MAX_E][2]usize,rotated:bool,masks:*[MAX_C]u64)bool{
    var order:[MAX_C]usize=@splat(0);for(0..c)|i|order[i]=i;if(rotated){var i:usize=1;while(i<c):(i+=1){const v=order[i];var j=i;while(j>0 and cells[order[j-1]].alt>cells[v].alt){order[j]=order[j-1];j-=1;}order[j]=v;}}
    var ea:[MAX_E]Point=@splat(.{.x=0,.y=0});var eb=ea;var ids:[MAX_E]usize=@splat(0);var keys:[MAX_E]i32=@splat(0);var m:usize=0;for(0..n)|id|if(edges[id].negative==rotated){const ab=sweepEdge(edges[id],rotated);ea[id]=ab[0];eb[id]=ab[1];const key=positiveKey(ea[id].x,ea[id].y);var j=m;m+=1;while(j>0 and (keys[j-1]>key or (keys[j-1]==key and ids[j-1]>id))){keys[j]=keys[j-1];ids[j]=ids[j-1];j-=1;}keys[j]=key;ids[j]=id;};
    var sl:[MAX_E]usize=@splat(0);var sb=sl;var sln:usize=0;var sbn:usize=0;for(0..c)|pos|{const cid=order[pos];const box=sweepBox(cells[cid],rotated);var cand:[16]usize=@splat(0);var cn:usize=0;while(sln>0 and segmentBox(edges[sl[sln-1]],cells[cid],rotated)){sln-=1;cand[cn]=sl[sln];cn+=1;}while(sbn>0 and segmentBox(edges[sb[sbn-1]],cells[cid],rotated)){sbn-=1;cand[cn]=sb[sbn];cn+=1;}for(0..m)|q|{const id=ids[q];if(endpoints[id][0]==cid){cand[cn]=id;cn+=1;}}
        var exits:[16]Exit=@splat(.{.edge=0,.side=0,.num=0,.den=1});var en:usize=0;for(0..cn)|q|{const id=cand[q];masks[cid]|=@as(u64,1)<<@intCast(id);if(endpoints[id][1]==cid)continue;const e=exitForCell(ea[id],eb[id],box,id) orelse return false;exits[en]=e;en+=1;}var i:usize=1;while(i<en):(i+=1){const v=exits[i];var j=i;while(j>0 and (exits[j-1].side>v.side or (exits[j-1].side==v.side and exitLess(v,exits[j-1])))){exits[j]=exits[j-1];j-=1;}exits[j]=v;}for(0..en)|q|{if(exits[q].side==0){if(sln>=MAX_E)return false;sl[sln]=exits[q].edge;sln+=1;}else{if(sbn>=MAX_E)return false;sb[sbn]=exits[q].edge;sbn+=1;}}
        if(pos+1==c)continue;var path:[33]Point=@splat(.{.x=0,.y=0});var pn:usize=0;var corner:usize=0;if(!frontier(cells,c,&order,pos+1,rotated,&path,&pn,&corner))return false;const nextbox=sweepBox(cells[order[pos+1]],rotated);if(nextbox[1]>box[1]){while(sln>0){const id=sl[sln-1];const where=frontierSegment(ea[id],eb[id],&path,pn);if(where<0)return false;if(@as(usize,@intCast(where))<corner)break;if(sbn>=MAX_E)return false;sb[sbn]=sl[sln-1];sbn+=1;sln-=1;}}else{while(sbn>0){const id=sb[sbn-1];const where=frontierSegment(ea[id],eb[id],&path,pn);if(where<0)return false;if(@as(usize,@intCast(where))>=corner)break;if(sln>=MAX_E)return false;sl[sln]=sb[sbn-1];sln+=1;sbn-=1;}}
    }return sln==0 and sbn==0;
}
fn putWord(out:[*]u8,at:usize,value:i64)void{const bits:u64=@bitCast(value);for(0..8)|b|out[at+b]=@truncate(bits>>@intCast(8*b));}

pub export fn k_quadtree_edge_distribution(input:[*c]const i64,length:usize,output:[*c]u8,capacity:usize)i64{
    if(input==null or length<2 or length>MAX_WORDS)return -1;const nv=input[0];const cv=input[1];if(nv<0 or nv>8 or cv<1 or cv>46)return -1;const n:usize=@intCast(nv);const c:usize=@intCast(cv);if(length!=2+2*c+4*n)return -1;
    var cells:[MAX_C]Cell=@splat(.{});var edges:[MAX_E]Edge=@splat(.{});var endpoints:[MAX_E][2]usize=@splat(.{0,0});var at:usize=2;var previous:i32=0;
    for(0..c)|i|{const d=input[at];const p=input[at+1];at+=2;if(d<0 or d>4 or p<0 or p>=(@as(i64,1)<<@intCast(2*d)))return -1;cells[i].depth=@intCast(d);cells[i].prefix=@intCast(p);const span:i32=1<<@intCast(2*(D-cells[i].depth));cells[i].lo=cells[i].prefix*span;if(cells[i].lo!=previous)return -1;previous=cells[i].lo+span;makeBox(&cells[i]);}
    if(previous!=256 or (n==0 and (c!=1 or cells[0].depth!=0 or cells[0].prefix!=0)))return -1;for(0..c)|i|cells[i].alt=altPrefix(cells[i].depth,cells[i].prefix)<<@intCast(2*(D-cells[i].depth));
    var pts:[16]Point=@splat(.{.x=0,.y=0});for(0..n)|i|{var x0=input[at];var y0=input[at+1];var x1=input[at+2];var y1=input[at+3];at+=4;if(x0<0 or x0>255 or y0<0 or y0>255 or x1<0 or x1>255 or y1<0 or y1>255 or x0%16==0 or y0%16==0 or x1%16==0 or y1%16==0)return -1;if((x0==x1 and y0==y1) or y0==y1)return -1;if(x0>x1 or (x0==x1 and y0>y1)){const tx=x0;const ty=y0;x0=x1;y0=y1;x1=tx;y1=ty;}if(x0==x1 and y1<=y0)return -1;edges[i]=.{.x0=@intCast(x0),.y0=@intCast(y0),.x1=@intCast(x1),.y1=@intCast(y1),.negative=y1<y0};pts[2*i]=.{.x=@intCast(x0),.y=@intCast(y0)};pts[2*i+1]=.{.x=@intCast(x1),.y=@intCast(y1)};var gx:i32=0;while(gx<=256):(gx+=16){var gy:i32=0;while(gy<=256):(gy+=16){const p=Point{.x=gx,.y=gy};if(orient(pts[2*i],pts[2*i+1],p)==0 and onSegment(pts[2*i],pts[2*i+1],p))return -1;}}for(0..2*i)|j|if(pts[j].x==x0 and pts[j].y==y0)return -1;for(0..2*i+1)|j|if(pts[j].x==x1 and pts[j].y==y1)return -1;for(0..i)|j|if(intersects(pts[2*i],pts[2*i+1],pts[2*j],pts[2*j+1]))return -1;const a=findCell(&cells,c,positiveKey(@intCast(x0),@intCast(y0)));const b=findCell(&cells,c,positiveKey(@intCast(x1),@intCast(y1)));if(a<0 or b<0)return -1;endpoints[i]=.{@intCast(a),@intCast(b)};cells[@intCast(a)].endpoints+=1;cells[@intCast(b)].endpoints+=1;}
    for(0..c)|i|if(cells[i].endpoints>1)return -1;var pd=[_]i32{0}**85;var pp=pd;var pc:usize=0;for(0..c)|i|{var d:i32=0;while(d<cells[i].depth):(d+=1){const p=cells[i].prefix>>@intCast(2*(cells[i].depth-d));var found=false;for(0..pc)|q|if(pd[q]==d and pp[q]==p){found=true;};if(!found){pd[pc]=d;pp[pc]=p;pc+=1;}}}for(0..pc)|q|{var occupied:u32=0;for(0..c)|i|{if(cells[i].endpoints==0 or cells[i].depth<=pd[q])continue;if(cells[i].prefix>>@intCast(2*(cells[i].depth-pd[q]))==pp[q])occupied|=@as(u32,1)<<@intCast((cells[i].prefix>>@intCast(2*(cells[i].depth-pd[q]-1)))&3);}if(@popCount(occupied)<2)return -1;}
    for(0..n)|i|{for(0..2)|dir|{const rotated=dir==1;if(edges[i].negative!=rotated)continue;var order=[_]usize{0}**MAX_C;for(0..c)|j|order[j]=j;if(rotated){var a:usize=1;while(a<c):(a+=1){const v=order[a];var j=a;while(j>0 and cells[order[j-1]].alt>cells[v].alt){order[j]=order[j-1];j-=1;}order[j]=v;}}var rs:usize=0;var re:usize=0;for(0..c)|j|{if(order[j]==endpoints[i][0])rs=j;if(order[j]==endpoints[i][1])re=j;}if(rs>re)return -1;}}
    var masks=[_]u64{0}**MAX_C;if(!runSweep(&cells,c,&edges,n,&endpoints,false,&masks) or !runSweep(&cells,c,&edges,n,&endpoints,true,&masks))return -1;const bytes=8*(1+c);if(output==null or capacity<bytes)return -2;putWord(output,0,@intCast(c));for(0..c)|i|putWord(output,8*(1+i),@intCast(masks[i]));return @intCast(bytes);
}
